for idx, branch in enumerate(self.branches):
    condition, runnable = branch

    expression_value = condition.invoke(
        input,
        config=patch_config(
            config,
            callbacks=run_manager.get_child(tag=f"condition:{idx + 1}"),
        ),
    )

    if expression_value:
        for chunk in runnable.stream(
            input,
            config=patch_config(
                config,
                callbacks=run_manager.get_child(tag=f"branch:{idx + 1}"),
            ),
            **kwargs,
        ):
            yield chunk
            if final_output_supported:
                if final_output is None:
                    final_output = chunk
                else:
                    try:
                        final_output = final_output + chunk  # type: ignore[operator]
                    except TypeError:
                        final_output = None
                        final_output_supported = False
        break
else:
    for chunk in self.default.stream(
        input,
        config=patch_config(
            config,
            callbacks=run_manager.get_child(tag="branch:default"),
        ),
        **kwargs,
    ):
        yield chunk
        if final_output_supported:
            if final_output is None:
                final_output = chunk
            else:
                try:
                    final_output = final_output + chunk  # type: ignore[operator]
                except TypeError:
                    final_output = None
                    final_output_supported = False

for attempt in self._sync_retrying(reraise=True):
    with attempt:
        result = super().invoke(
            input_,
            self._patch_config(config, run_manager, attempt.retry_state),
            **kwargs,
        )
    if attempt.retry_state.outcome and not attempt.retry_state.outcome.failed:
        attempt.retry_state.set_result(result)

for runnable in self.runnables:
    try:
        if self.exception_key and last_error is not None:
            input[self.exception_key] = last_error  # type: ignore[index]
        child_config = patch_config(config, callbacks=run_manager.get_child())
        with set_config_context(child_config) as context:
            output = context.run(
                runnable.invoke,
                input,
                config,
                **kwargs,
            )
    except self.exceptions_to_handle as e:
        if first_error is None:
            first_error = e
        last_error = e
    except BaseException as e:
        run_manager.on_chain_error(e)
        raise
    else:
        run_manager.on_chain_end(output)
        return output

for i, step in enumerate(self.steps):
    # mark each step as a child run
    config = patch_config(
        config, callbacks=run_manager.get_child(f"seq:step:{i + 1}")
    )
    with set_config_context(config) as context:
        if i == 0:
            part = functools.partial(step.ainvoke, input_, config, **kwargs)
        else:
            part = functools.partial(step.ainvoke, input_, config)
        input_ = await coro_with_context(part(), context, create_task=True)
